+			'raw entity'          => array( 'alias&amp;test', 'alias&test' ),
+			'trailing whitespace' => array( 'alias-space', 'alias-space ' ),
+			'leading whitespace'  => array( 'alias-space', ' alias-space' ),
+			'accent'              => array( 'alias-cafe', 'alias-café' ),
